/*
 let processing.js version of let Soule's  let Life by let Chaos:
https://youtu.be/xiUpAeos168?feature=shared

 let version by let Carlos let Campuzano
 https://www.dynamicmath.xyz
 7/Jul/2024

 p5js version with music:
 https://openprocessing.org/sketch/2312160

 Three.js version with music:
 https://www.dynamicmath.xyz/threejs/particle-life/

 let source code here:
 https://github.com/jcponce/jcponce.github.io/tree/master/sketches/particle-life/particle-life

 let first attempt:
 https://openprocessing.org/sketch/2265246
/*************************************************************/


let numTypes;
let colorStep;
let numParticles = 1000;
ArrayList<Particle> swarm;

float [][] forces;
float [][] minDistances;
float [][] radii;

/*************************************************************/
function setup() {
  //createCanvas(750, 500);
	createCanvas(windowWidth, windowHeight, WEBGL);
  colorMode(HSB, 360, 100, 100);
  noStroke();

	numTypes = int(random(2, 21));
  colorStep = 360 / numTypes;

  swarm = new ArrayList<Particle>();
  for (i = 0; i < numParticles; i++) {
    swarm.add(new Particle());
  }
  forces = new float [numTypes][numTypes];
  minDistances = new float [numTypes][numTypes];
  radii = new float [numTypes][numTypes];
  setParameters();
}

/*************************************************************/
function draw() {
  background(0);

  for (let p of swarm) {
    p.update();
    p.display();
  }

	textAlign( CENTER, CENTER);
	fill(360);text("forces",numTypes*50+20,10);
	for( i=0 ; i<numTypes; i++){
		fill(i * colorStep, 100, 100);
		text(i,10,30+i*20);
		text(i,30+i*50,10);
		fill(360);
		for( j=0 ; j<numTypes; j++){
			forces[i][j]<0?fill(0,100,-forces[i][j]*100):fill(270,100,forces[i][j]*100);
			//fill(360*(forces[i][j]>0));
			text(forces[i][j], 30+j*50, 30+i*20);
		}
	}
}

/*************************************************************/
function mousePressed(){
//  setParameters();
}
/**************************\
        	I.O.
\**************************/
function keyPressed() {
	switch (key) {
		case ' ':
			setParameters();
			break;
	}
}


/*************************************************************/
function setParameters() {
  for (i = 0; i < numTypes; i++) {
    for (j = 0; j < numTypes; j++) {
      forces[i ][j ] = random(0.3, 1.0);
      if (random(100)<50) {
        forces[i][j]*=-1;
      }
      minDistances[i][j]=random(30, 50);
      radii[i][j]=random(70, 250);
    }
  }
}


let K = 0.05;
let friction = 1-0.15;

/*************************************************************/
class Particle {

  position;
  velocity;
  type;

  constructor() {
		let rad = random(100);
		let ang = random(TWO_PI);
		position = new PVector(rad * cos(ang) + width/2, rad * sin(ang)+height/2);
    velocity = new PVector(0, 0);
    type = int(random(numTypes));
  }

  function update() {
    let direction = new PVector(0, 0);
    let totalForce = new PVector(0, 0);
    let acceleration = new PVector(0, 0);
    let distance;
    for (let p of swarm) {
      if (p != this) {
   //     direction.mult(0); ligne inutile étant donné la ligne ci-dessous
        direction = new PVector(p.position.x, p.position.y);
        direction.sub(position);
        if (direction.x>0.5*width) {
          direction.x-=width;
        }
        if (direction.x<-0.5*width) {
          direction.x+=width;
        }
        if (direction.y>0.5*height) {
          direction.y-=height;
        }
        if (direction.y<-0.5*height) {
          direction.y+=height;
        }

        distance = direction.mag();
        direction.normalize();
        if (distance < minDistances[type][p.type]) {
          let force = new PVector(direction.x, direction.y);
          force.mult(abs(forces[type][p.type]) * (-3));
          force.mult(map(distance, 0, minDistances[type][p.type], 1, 0));
          force.mult(K);
          totalForce.add(force);
        }
        if(distance < radii[type][p.type]){
        var force = new PVector(direction.x, direction.y);
          force.mult(forces[type][p.type]);
          force.mult(map(distance, 0, radii[type][p.type], 1, 0));
          force.mult(K);
          totalForce.add(force);
        }

      }
    }

    acceleration.add(totalForce);
    velocity.add(acceleration);
    position.add(velocity);
    position.x = (position.x+width)%width;
    position.y = (position.y+height)%height;
    velocity.mult(friction);
  }



  function display() {
    fill(this.type * colorStep, 100, 100);
    ellipse(this.position.x, this.position.y, 3, 3);
  }
}

